// Package slug generates session identifiers (D3).
package slug

import (
	"crypto/rand"
	"io"
	"strings"
)

// Length is the number of characters in a slug.
const Length = 10

const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

// limit is 62*4: bytes below this threshold are distributed uniformly
// over the alphabet with `b % 62`, without modulo bias.
const limit = 248

// New generates a slug with crypto/rand.
func New() (string, error) {
	return generate(rand.Reader)
}

// Valid reports whether s has the length and alphabet of a slug generated by New.
func Valid(s string) bool {
	if len(s) != Length {
		return false
	}
	for i := 0; i < len(s); i++ {
		if strings.IndexByte(alphabet, s[i]) < 0 {
			return false
		}
	}
	return true
}

func generate(r io.Reader) (string, error) {
	out := make([]byte, 0, Length)
	buf := make([]byte, 2*Length)
	for len(out) < Length {
		if _, err := io.ReadFull(r, buf); err != nil {
			return "", err
		}
		for _, b := range buf {
			if int(b) < limit && len(out) < Length {
				out = append(out, alphabet[int(b)%len(alphabet)])
			}
		}
	}
	return string(out), nil
}
